#include <vector>

class Solution {
public:
    int getWinner(std::vector<int>& arr, int k) {
        int cur = arr[0], wins = 0;
        for (size_t i = 1; i < arr.size(); ++i) {
            if (arr[i] > cur) {
                cur = arr[i];
                wins = 1;
            } else {
                wins++;
            }
            if (wins == k) return cur;
        }
        return cur;
    }
};

